/* Set TikTok ads dashboard date range (default: yesterday). No // comments (minified to one line). */
(async function () {
  var MODE = '__DATE_MODE__';

  function sleep(ms) {
    return new Promise(function (r) {
      setTimeout(r, ms);
    });
  }

  function cleanText(t) {
    return String(t == null ? '' : t)
      .replace(/\s+/g, ' ')
      .trim();
  }

  function pad2(n) {
    return (n < 10 ? '0' : '') + n;
  }

  function formatYmd(d) {
    return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate());
  }

  function targetDates(mode) {
    var today = new Date();
    today.setHours(0, 0, 0, 0);
    var y = new Date(today.getTime());
    y.setDate(y.getDate() - 1);
    if (mode === 'today') {
      return { start: formatYmd(today), end: formatYmd(today), labels: ['今天', '今日', 'Today', 'today'] };
    }
    if (mode === 'custom') {
      return { start: null, end: null, labels: [] };
    }
    return {
      start: formatYmd(y),
      end: formatYmd(y),
      labels: ['昨天', '昨日', 'Yesterday', 'yesterday']
    };
  }

  function parseRangeFromText(text) {
    var t = cleanText(text);
    var m = t.match(/(\d{4}[-\/]\d{1,2}[-\/]\d{1,2})\s*[-–~至到]\s*(\d{4}[-\/]\d{1,2}[-\/]\d{1,2})/);
    if (!m) return null;
    function norm(s) {
      var p = s.replace(/\//g, '-').split('-');
      return p[0] + '-' + pad2(Number(p[1])) + '-' + pad2(Number(p[2]));
    }
    return { start: norm(m[1]), end: norm(m[2]), raw: m[0] };
  }

  function isVisible(el) {
    if (!el || el.nodeType !== 1) return false;
    var st = window.getComputedStyle(el);
    if (!st || st.display === 'none' || st.visibility === 'hidden' || Number(st.opacity) === 0) {
      return false;
    }
    var r = el.getBoundingClientRect();
    return r.width > 0 && r.height > 0;
  }

  function clickEl(el) {
    if (!el) return false;
    try {
      el.scrollIntoView({ block: 'center', inline: 'center' });
    } catch (e) {}
    try {
      el.focus && el.focus();
    } catch (e2) {}
    var opts = { bubbles: true, cancelable: true, view: window };
    try {
      el.dispatchEvent(new MouseEvent('mousedown', opts));
      el.dispatchEvent(new MouseEvent('mouseup', opts));
      el.dispatchEvent(new MouseEvent('click', opts));
    } catch (e3) {
      try {
        el.click();
      } catch (e4) {
        return false;
      }
    }
    return true;
  }

  function readDisplayedRange() {
    var nodes = document.querySelectorAll('input, button, div, span, p, a');
    var best = null;
    for (var i = 0; i < nodes.length && i < 5000; i++) {
      var el = nodes[i];
      if (!isVisible(el)) continue;
      var text = '';
      if (el.tagName === 'INPUT') text = el.value || el.getAttribute('placeholder') || '';
      else text = el.innerText || el.textContent || '';
      text = cleanText(text).slice(0, 80);
      var rg = parseRangeFromText(text);
      if (!rg) continue;
      var r = el.getBoundingClientRect();
      if (r.top > window.innerHeight * 0.55) continue;
      best = { el: el, range: rg, text: text };
      if (el.tagName === 'INPUT' || /picker|date|calendar|range/i.test(el.className || '')) break;
    }
    return best;
  }

  function findDateTrigger() {
    var shown = readDisplayedRange();
    if (shown && shown.el) {
      var cur = shown.el;
      for (var d = 0; d < 6 && cur; d++) {
        if (
          cur.matches &&
          cur.matches(
            'button, [role="button"], input, .arco-picker, .arco-picker-range, [class*="picker"], [class*="Picker"], [class*="date"], [class*="Date"]'
          )
        ) {
          return { el: cur, range: shown.range, via: 'range-text' };
        }
        cur = cur.parentElement;
      }
      return { el: shown.el, range: shown.range, via: 'range-text' };
    }

    var sels = [
      '.arco-picker-range',
      '.arco-picker',
      '[class*="RangePicker"]',
      '[class*="range-picker"]',
      '[class*="DatePicker"]',
      '[class*="date-picker"]',
      'input[placeholder*="日期"]',
      'input[placeholder*="Date"]',
      'input[placeholder*="Start"]',
      '[data-testid*="date"]',
      '[data-e2e*="date"]'
    ];
    for (var s = 0; s < sels.length; s++) {
      var list = document.querySelectorAll(sels[s]);
      for (var j = 0; j < list.length; j++) {
        if (isVisible(list[j])) return { el: list[j], range: null, via: sels[s] };
      }
    }
    return null;
  }

  function findShortcut(labels) {
    var nodes = document.querySelectorAll(
      'button, a, li, div, span, [role="button"], [role="option"], [role="menuitem"]'
    );
    var candidates = [];
    for (var i = 0; i < nodes.length && i < 8000; i++) {
      var el = nodes[i];
      if (!isVisible(el)) continue;
      var t = cleanText(el.innerText || el.textContent || '');
      if (!t || t.length > 20) continue;
      for (var k = 0; k < labels.length; k++) {
        if (t === labels[k] || t.toLowerCase() === String(labels[k]).toLowerCase()) {
          candidates.push({ el: el, text: t, exact: true });
          break;
        }
      }
    }
    if (!candidates.length) {
      for (var i2 = 0; i2 < nodes.length && i2 < 8000; i2++) {
        var el2 = nodes[i2];
        if (!isVisible(el2)) continue;
        var t2 = cleanText(el2.innerText || el2.textContent || '');
        if (!t2 || t2.length > 20) continue;
        for (var k2 = 0; k2 < labels.length; k2++) {
          var lab = String(labels[k2]);
          if (t2.indexOf(lab) >= 0 || t2.toLowerCase().indexOf(lab.toLowerCase()) >= 0) {
            candidates.push({ el: el2, text: t2, exact: false });
            break;
          }
        }
      }
    }
    if (!candidates.length) return null;
    candidates.sort(function (a, b) {
      return (b.exact ? 1 : 0) - (a.exact ? 1 : 0) || a.text.length - b.text.length;
    });
    return candidates[0];
  }

  function panelOpen() {
    var panelSels = [
      '.arco-picker-container',
      '.arco-trigger-popup',
      '.arco-panel-date',
      '[class*="picker-container"]',
      '[class*="PickerDropdown"]',
      '[class*="datepicker"]',
      '[class*="DatePicker"]',
      '[class*="calendar-panel"]',
      '[class*="shortcut"]'
    ];
    for (var i = 0; i < panelSels.length; i++) {
      var els = document.querySelectorAll(panelSels[i]);
      for (var j = 0; j < els.length; j++) {
        if (isVisible(els[j])) return true;
      }
    }
    var labels = ['今天', '昨天', '近7天', 'Today', 'Yesterday', 'Last 7 days'];
    return !!findShortcut(labels);
  }

  var mode = String(MODE || 'yesterday').toLowerCase();
  if (mode !== 'today' && mode !== 'yesterday') mode = 'yesterday';
  var target = targetDates(mode);
  var before = readDisplayedRange();
  var beforeRange = before ? before.range : null;

  if (
    beforeRange &&
    target.start &&
    beforeRange.start === target.start &&
    beforeRange.end === target.end
  ) {
    return JSON.stringify({
      ok: true,
      skipped: true,
      mode: mode,
      before: beforeRange,
      after: beforeRange,
      message: 'already on target range'
    });
  }

  var trigger = findDateTrigger();
  if (!trigger || !trigger.el) {
    return JSON.stringify({
      ok: false,
      mode: mode,
      before: beforeRange,
      error: '未找到日期选择器（页面上无 2026-xx-xx - 2026-xx-xx 类控件）'
    });
  }

  clickEl(trigger.el);
  await sleep(450);
  if (!panelOpen()) {
    var parent = trigger.el.parentElement;
    if (parent) clickEl(parent);
    await sleep(450);
  }
  if (!panelOpen()) {
    var icon =
      document.querySelector('[class*="calendar"]') ||
      document.querySelector('[class*="Calendar"]') ||
      document.querySelector('svg[class*="calendar"]');
    if (icon) {
      clickEl(icon.closest ? icon.closest('button, div, span') || icon : icon);
      await sleep(450);
    }
  }

  var sc = findShortcut(target.labels);
  if (!sc) {
    return JSON.stringify({
      ok: false,
      mode: mode,
      before: beforeRange,
      triggerVia: trigger.via,
      panelOpen: panelOpen(),
      error: '已打开日期区但未找到快捷项: ' + target.labels.join('/')
    });
  }

  clickEl(sc.el);
  await sleep(900);

  var applyBtns = findShortcut(['确定', '应用', 'Apply', 'OK', '确认', 'Done']);
  if (applyBtns && /确定|应用|Apply|OK|确认|Done/i.test(applyBtns.text)) {
    clickEl(applyBtns.el);
    await sleep(600);
  }

  var after = null;
  for (var w = 0; w < 20; w++) {
    await sleep(400);
    var cur = readDisplayedRange();
    after = cur ? cur.range : null;
    if (
      after &&
      target.start &&
      after.start === target.start &&
      after.end === target.end
    ) {
      break;
    }
    if (
      after &&
      beforeRange &&
      (after.start !== beforeRange.start || after.end !== beforeRange.end)
    ) {
      break;
    }
  }

  var matched =
    !!(after && target.start && after.start === target.start && after.end === target.end);
  var changed =
    !!(after && beforeRange && (after.start !== beforeRange.start || after.end !== beforeRange.end));

  return JSON.stringify({
    ok: matched || changed,
    skipped: false,
    mode: mode,
    clicked: sc.text,
    triggerVia: trigger.via,
    before: beforeRange,
    after: after,
    target: { start: target.start, end: target.end },
    message: matched
      ? 'date range set to ' + mode
      : changed
        ? 'date range changed (soft ok)'
        : 'date click done but range not confirmed',
    error: matched || changed ? null : '点击「' + sc.text + '」后日期显示未变为目标区间'
  });
})();

