      $hit = Convert-MaybeJsonString $c
      if ($hit) { return $hit }
    }
  }

  if ($execOut -match '(?s)(\{\s*"ok"\s*:\s*(?:true|false)[\s\S]{0,4000}\})') {
    $m = ConvertFrom-JsonSafe $Matches[1]
    if ($m -and (& $shapeTest $m)) { return $m }
  }
  return $null
}

