$summary = @()
$allCampaignRows = @()
$scrapeOneLine = ConvertTo-ScrapeOneLine $scrapeJs
$dateRangeJs = $dateRangeJsTemplate.Replace('__DATE_MODE__', $dateMode)
$dateRangeOneLine = ConvertTo-ScrapeOneLine $dateRangeJs
Write-Step ("scrape script one-line length={0}" -f $scrapeOneLine.Length)
Write-Step ("date-range script one-line length={0} mode={1}" -f $dateRangeOneLine.Length, $dateMode)

function Invoke-SetPageDateRange([string]$storeId) {
  if (-not $setPageDateRange) {
    Write-Step "  skip set page date range (options.setPageDateRange=false)"
    return $true
  }
  Write-Step ("  set page date range => {0}..." -f $dateMode)
  $dateOut = $null
  try {
    $dateOut = Invoke-Ziniao @(
      'page', 'exec',
      '--store-id', $storeId,
      '--script', $dateRangeOneLine,
      '--timeout', '45000'
    )
    Write-Host $dateOut
  } catch {
    Write-Step ("  WARN set date range exec failed: {0}" -f $_)
    return $false
  }

  $dr = Get-DateRangePayload $dateOut
  if ($null -eq $dr) {
    Write-Step "  WARN set date range: unrecognized payload (will still scrape)"
    return $false
  }
  if ($dr.skipped) {
    Write-Step ("  date range already {0}: {1} ~ {2}" -f $dateMode, $dr.after.start, $dr.after.end)
  } elseif ($dr.ok) {
    $beforeTxt = if ($dr.before) { "{0}~{1}" -f $dr.before.start, $dr.before.end } else { '?' }
    $afterTxt = if ($dr.after) { "{0}~{1}" -f $dr.after.start, $dr.after.end } else { '?' }
    Write-Step ("  date range ok clicked={0} before={1} after={2}" -f $dr.clicked, $beforeTxt, $afterTxt)
  } else {
    Write-Step ("  WARN set date range failed: {0}" -f $(if ($dr.error) { $dr.error } else { 'unknown' }))
  }

  if ($waitAfterDateChangeMs -gt 0) {
    Write-Step ("  wait after date change {0}ms (table reload)..." -f $waitAfterDateChangeMs)
    Start-Sleep -Milliseconds $waitAfterDateChangeMs
  }
  return [bool]$dr.ok
}

