  [void]$md.AppendLine(("| 销量合计 | {0} |" -f $totalOrders))
  [void]$md.AppendLine(("| 销售额合计 (USD) | {0} |" -f $totalRevenue))
  [void]$md.AppendLine(("| 综合 ROI | {0} |" -f $overallRoi))
  [void]$md.AppendLine("")
  [void]$md.AppendLine("> 金额单位：**美金 (USD)**，与 TikTok 广告后台一致。")
  [void]$md.AppendLine("")
