$root = 'E:\project\海外TK店铺广告投流数据自动化监测'
$stamp = Get-Date -Format 'yyyyMMdd-HHmm'
$outDir = Join-Path $root 'dist'
New-Item -ItemType Directory -Force -Path $outDir | Out-Null
$zipName = "TK广告投流监测-full-with-secrets-$stamp.zip"
$zipPath = Join-Path $outDir $zipName
$tmp = Join-Path $env:TEMP ("tk-full-pack-" + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Force -Path $tmp | Out-Null
try {
  $dest = Join-Path $tmp 'TK广告投流监测'
  New-Item -ItemType Directory -Force -Path $dest | Out-Null
  $excludeDirNames = @('.git', '__pycache__', 'node_modules', '.grok', 'dist', '_extract')
  Get-ChildItem -LiteralPath $root -Force | ForEach-Object {
    if ($_.PSIsContainer -and ($excludeDirNames -contains $_.Name)) { return }
    if (-not $_.PSIsContainer -and $_.Name -like '*.zip') { return }
    Copy-Item -LiteralPath $_.FullName -Destination (Join-Path $dest $_.Name) -Recurse -Force
  }
  # strip python cache under copied tree
  Get-ChildItem -LiteralPath $dest -Recurse -Directory -Filter '__pycache__' -ErrorAction SilentlyContinue | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
  if (Test-Path $zipPath) { Remove-Item -LiteralPath $zipPath -Force }
  Compress-Archive -Path $dest -DestinationPath $zipPath -Force
  $fi = Get-Item -LiteralPath $zipPath
  Write-Host ("OK full: {0}" -f $fi.FullName)
  Write-Host ("size_MB: {0:N2}" -f ($fi.Length / 1MB))
} finally {
  Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
}
Get-ChildItem -LiteralPath $outDir | Sort-Object LastWriteTime -Descending | Select-Object -First 8 Name, @{N='MB';E={[math]::Round($_.Length/1MB,2)}}, LastWriteTime | Format-Table -AutoSize

